const require_browser = require("../utils/browser.js");
let react = require("react");
let lodash_es = require("lodash-es");
//#region src/useIdle/index.ts
const defaultEvents = [
	"mousemove",
	"mousedown",
	"resize",
	"keydown",
	"touchstart",
	"wheel"
];
const oneMinute = 6e4;
const useIdle = (ms = oneMinute, initialState = false, events = defaultEvents) => {
	const [state, setState] = (0, react.useState)(initialState);
	(0, react.useEffect)(() => {
		let mounted = true;
		let timeout;
		let localState = state;
		const set = (newState) => {
			if (mounted) {
				localState = newState;
				setState(newState);
			}
		};
		const onEvent = (0, lodash_es.throttle)(() => {
			if (localState) set(false);
			clearTimeout(timeout);
			timeout = setTimeout(() => set(true), ms);
		}, 50);
		const onVisibility = () => {
			if (!document.hidden) onEvent();
		};
		for (let i = 0; i < events.length; i++) require_browser.on(window, events[i], onEvent);
		require_browser.on(document, "visibilitychange", onVisibility);
		timeout = setTimeout(() => set(true), ms);
		return () => {
			mounted = false;
			for (let i = 0; i < events.length; i++) require_browser.off(window, events[i], onEvent);
			require_browser.off(document, "visibilitychange", onVisibility);
		};
	}, [ms, events]);
	return state;
};
//#endregion
exports.useIdle = useIdle;
